    $path=str_replace('\\','/',realpath(__DIR__.'/.medicine319-validation/data')?:'MISSING');
    if(!str_starts_with($meta['version'],'10.4.27-')||(int)$meta['port']!==3339||strcasecmp(rtrim(str_replace('\\','/',$meta['datadir']),'/'),$path)!==0||$meta['sql_mode']!==M319_MODE||$meta['global_mode']!==M319_MODE){throw new RuntimeException('Phase 3.19 disposable isolation guard failed.');}return $pdo;
}
function m319Db(PDO $pdo):App\Core\Database {$db=(new ReflectionClass(App\Core\Database::class))->newInstanceWithoutConstructor();(new ReflectionProperty(App\Core\Database::class,'pdo'))->setValue($db,$pdo);return $db;}
