function m319SqlReject(callable $action,array $codes=[1644,4025]):void {try{$action();}catch(PDOException $e){medicineCheck(in_array((int)($e->errorInfo[1]??0),$codes,true),'Unexpected disposable integrity error');return;}throw new RuntimeException('Forbidden SQL accepted');}
