function m319Race(array $jobs):array {
    $work=__DIR__.'/.medicine319-validation';foreach(['ready1','ready2','go'] as $file){if(is_file($work.'/'.$file)){unlink($work.'/'.$file);}}
    $processes=[];foreach($jobs as $n=>$job){file_put_contents($work.'/job'.$n.'.json',json_encode($job,JSON_THROW_ON_ERROR));$processes[$n]=proc_open([PHP_BINARY,__FILE__,'worker',(string)$n],[0=>['pipe','r'],1=>['file',$work.'/out'.$n.'.json','w'],2=>['file',$work.'/err'.$n,'w']],$pipes);if(!is_resource($processes[$n])){throw new RuntimeException('Worker failed to start');}fclose($pipes[0]);}
    $deadline=microtime(true)+20;while(!is_file($work.'/ready1')||!is_file($work.'/ready2')){if(microtime(true)>$deadline){throw new RuntimeException('Worker readiness timeout');}usleep(10000);}file_put_contents($work.'/go','go');
    $results=[];foreach($processes as $n=>$process){medicineCheck(proc_close($process)===0,'Worker failed; inspect disposable diagnostics');$results[]=json_decode(file_get_contents($work.'/out'.$n.'.json'),true,64,JSON_THROW_ON_ERROR);}return $results;
}
